/* FRU · Formulario de Registro de Usuario Adicional (Módulo 01 · Onboarding).
   Ningún color literal: todo sale del vocabulario de `tokens.css`. */

/* La raíz es hija directa de `.bwcnt` (overflow: hidden): el scroll es suyo. */
.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 52px 48px 56px;
}

.column {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
}

.eyebrow {
  margin: 0 0 10px;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: var(--bw-size-eyebrow);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-brass);
}

.title {
  margin: 0 0 6px;
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: var(--bw-size-title);
  letter-spacing: var(--bw-ls-title);
  line-height: 1.25;
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0 0 24px;
  font-size: var(--bw-size-body);
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

.subtitle strong {
  font-weight: 600;
  color: var(--bw-ink-steel);
}

/* Aviso de rol: informativo, no hay selector. */
.roleBadge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  align-self: flex-start;
  margin-bottom: 28px;
  padding: 4px 12px 4px 10px;
  background: var(--bw-cold-white);
  border: 1px solid var(--bw-line-steel);
  border-radius: 20px;
  font-size: var(--bw-size-label);
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

.roleBadge strong {
  font-weight: 600;
  color: var(--bw-ink-steel);
}

.roleDot {
  width: 6px;
  height: 6px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--bw-input-placeholder);
}

.form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.row {
  display: flex;
  flex-direction: column;
}

.label {
  display: block;
  margin-bottom: 5px;
  font-size: var(--bw-size-label);
  font-weight: 500;
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-ink-steel);
}

.input {
  width: 100%;
  padding: var(--bw-pad-input);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: transparent;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.input:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.input::placeholder {
  color: var(--bw-input-placeholder);
}

.hint {
  margin-top: 4px;
  font-size: var(--bw-size-hint);
  line-height: 1.5;
  letter-spacing: var(--bw-ls-hint);
  color: var(--bw-input-placeholder);
}

.fieldError {
  margin-top: 4px;
  font-size: var(--bw-size-label);
  line-height: 1.5;
  color: var(--bw-error-text);
}

.emailOk {
  margin-top: 4px;
  font-size: var(--bw-size-label);
  line-height: 1.5;
  color: var(--bw-signal-green);
}

.status {
  margin-top: 4px;
  font-size: var(--bw-size-label);
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

.alert {
  margin-top: 4px;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  font-size: var(--bw-size-label);
  line-height: 1.5;
  color: var(--bw-error-text);
}

.check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-ink-steel);
}

.check input[type='checkbox'] {
  width: 16px;
  height: 16px;
  margin: 2px 0 0;
  flex-shrink: 0;
  accent-color: var(--bw-calibration-blue);
  cursor: pointer;
}

.check a {
  color: var(--bw-calibration-blue);
  text-decoration: none;
}

.check a:hover {
  text-decoration: underline;
}

.button {
  display: block;
  width: 100%;
  padding: 13px 20px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  /* Sobre el azul de acción no hay blanco puro en el vocabulario: se usa el
     blanco frío del sistema, que es el más cercano. */
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s;
}

.button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.button:not(:disabled):hover {
  opacity: 0.9;
}

.success {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
  padding: 14px 16px;
  border-left: 3px solid var(--bw-signal-green);
  border-radius: 0 var(--bw-radius) var(--bw-radius) 0;
  background: var(--bw-tint-oferta);
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-success-dark);
}

.success svg {
  flex-shrink: 0;
}

.successButton {
  margin-bottom: 10px;
}

.secondaryButton {
  background: var(--bw-cold-white);
  color: var(--bw-ink-steel);
}

import { useRef, useState, type ChangeEvent, type FormEvent } from 'react';
import {
  EMAIL_HINT,
  NAME_HINT,
  PASSWORD_HINT,
  PASSWORD_MISMATCH,
  canRegister,
  isValidName,
  isValidPassword,
  registerAdditionalMember,
  type NewMemberForm,
} from '../../lib/onboarding';
import { emailHasAccount, isValidEmail } from '../../lib/invitations';
import { errorMessage, type MemberProfile } from '../../lib/session';
import styles from './AdditionalUser.module.css';

/** Los textos del HTML aprobado, literales: los tests los buscan tal cual. */
const EMAIL_CHECKING = 'Verificando disponibilidad…';
const EMAIL_FREE = 'Email disponible.';
const EMAIL_TAKEN = 'Este email ya está registrado en la plataforma.';
const PASSWORD_RULES =
  'Mínimo 10 caracteres, 1 mayúscula, 1 minúscula, 1 número y 1 símbolo.';
const REGISTERED = 'Usuario registrado correctamente.';

/** El resultado de la comprobación, JUNTO AL TEXTO al que corresponde. */
interface EmailCheck {
  email: string;
  hasAccount: boolean;
}

function asError(err: unknown): Error {
  return err instanceof Error ? err : new Error(String(err));
}

/**
 * FRU · Formulario de Registro de Usuario Adicional (Módulo 01 · Onboarding).
 *
 * Es la PANTALLA: posee todo el estado y es el único sitio que llama a la red.
 * Solo la ve un ADMIN en `KEY_ACTIVE`, dentro del shell estándar.
 *
 * Tres decisiones que no se leen en el JSX:
 *
 * - **Sin selector de rol ni campo de organización**, ni siquiera de solo
 *   lectura: el miembro entra como `Editor` y queda vinculado a la
 *   organización de quien lo da de alta. El aviso de rol es informativo.
 * - **La comprobación del email guarda el TEXTO con el resultado.** Sin la
 *   pareja `{email, hasAccount}` no se puede distinguir una respuesta buena de
 *   la de un texto que el usuario ya ha borrado; con ella, una respuesta tardía
 *   se descarta sola (misma técnica que `Invitations.tsx`). Sin debounce. Y un
 *   rechazo es «no se sabe»: ni mensaje ni bloqueo, la Edge Function lo vuelve
 *   a comprobar al registrar.
 * - **Un solo `submitting`** deshabilita el botón y evita el doble alta: la
 *   contraseña viaja a la Edge Function y a ningún otro sitio — nunca se
 *   escribe en pantalla ni en consola.
 */
export function AdditionalUser({
  profile,
  onGoToPanel,
}: {
  profile: MemberProfile;
  onGoToPanel: () => Promise<void>;
}) {
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [repeat, setRepeat] = useState('');
  const [acceptedTerms, setAcceptedTerms] = useState(false);

  const [check, setCheck] = useState<EmailCheck | null>(null);
  const [checking, setChecking] = useState(false);
  const checkSeq = useRef(0);

  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [registered, setRegistered] = useState(false);

  const [panelError, setPanelError] = useState<string | null>(null);

  /** Volver al formulario en blanco, con los mensajes y la comprobación borrados. */
  function resetForm() {
    checkSeq.current += 1;
    setFullName('');
    setEmail('');
    setPassword('');
    setRepeat('');
    setAcceptedTerms(false);
    setCheck(null);
    setChecking(false);
    setSubmitError(null);
  }

  function handleNameChange(event: ChangeEvent<HTMLInputElement>) {
    setFullName(event.target.value);
  }

  function handlePasswordChange(event: ChangeEvent<HTMLInputElement>) {
    setPassword(event.target.value);
  }

  function handleRepeatChange(event: ChangeEvent<HTMLInputElement>) {
    setRepeat(event.target.value);
  }

  function handleTermsChange(event: ChangeEvent<HTMLInputElement>) {
    setAcceptedTerms(event.target.checked);
  }

  /**
   * Sin debounce: cada texto válido consulta. La secuencia descarta lo tardío y
   * el texto sigue viajando con el resultado, que es lo que decide si se pinta.
   * Un texto inválido no consulta nada.
   */
  function handleEmailChange(event: ChangeEvent<HTMLInputElement>) {
    const value = event.target.value;

    setEmail(value);
    setCheck(null);

    if (!isValidEmail(value)) {
      checkSeq.current += 1;
      setChecking(false);
      return;
    }

    const seq = checkSeq.current + 1;
    checkSeq.current = seq;
    setChecking(true);

    emailHasAccount(value)
      .then((hasAccount) => {
        if (seq !== checkSeq.current) return;
        setCheck({ email: value, hasAccount });
      })
      .catch(() => {
        // «No se sabe» no es «sí»: no se dice nada y el servidor decidirá.
        if (seq !== checkSeq.current) return;
        setCheck(null);
      })
      .finally(() => {
        if (seq === checkSeq.current) setChecking(false);
      });
  }

  const form: NewMemberForm = { fullName, email, password, repeat, acceptedTerms };
  const emailTaken = check !== null && check.email === email && check.hasAccount;
  const emailAvailable = check !== null && check.email === email && !check.hasAccount;
  const canSubmit = canRegister(form, emailTaken) && !checking && !submitting;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canSubmit) return;

    setSubmitting(true);
    setSubmitError(null);

    registerAdditionalMember({ fullName, email, password })
      .then(() => {
        resetForm();
        setRegistered(true);
      })
      .catch((err: unknown) => {
        // El formulario NO se vacía: lo escrito es lo que hay que corregir.
        setSubmitError(errorMessage(asError(err)));
      })
      .finally(() => {
        setSubmitting(false);
      });
  }

  function handleAddAnother() {
    resetForm();
    setPanelError(null);
    setRegistered(false);
  }

  async function handleGoToPanel() {
    setPanelError(null);
    try {
      await onGoToPanel();
    } catch (err: unknown) {
      setPanelError(errorMessage(asError(err)));
    }
  }

  return (
    <div className={styles.screen}>
      <div className={styles.column}>
        <p className={styles.eyebrow}>Módulo 01 · Onboarding</p>
        <h1 className={styles.title}>Registro de usuario adicional</h1>
        <p className={styles.subtitle}>Completa los datos del nuevo miembro. Tendrá acceso inmediato a la cuenta de <strong>{profile.orgName}</strong>.</p>

        <div className={styles.roleBadge}>
          <span className={styles.roleDot} aria-hidden="true" />
          <span>Se registrará con rol <strong>Editor</strong> — asignado automáticamente</span>
        </div>

        {registered ? (
          <>
            <p className={styles.success} role="status">
              <svg
                width="18"
                height="18"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
                focusable="false"
              >
                <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                <polyline points="22 4 12 14.01 9 11.01" />
              </svg>
              <span>{REGISTERED}</span>
            </p>

            <button
              type="button"
              className={`${styles.button} ${styles.successButton}`}
              onClick={handleAddAnother}
            >
              Añadir otro usuario
            </button>

            <button
              type="button"
              className={`${styles.button} ${styles.secondaryButton}`}
              onClick={handleGoToPanel}
            >
              Ir al panel
            </button>

            {panelError !== null && (
              <p className={styles.alert} role="alert">
                {panelError}
              </p>
            )}
          </>
        ) : (
          <form className={styles.form} noValidate onSubmit={handleSubmit}>
            <div className={styles.row}>
              <label className={styles.label} htmlFor="fru-name">
                Nombre completo
              </label>
              <input
                id="fru-name"
                className={styles.input}
                type="text"
                autoComplete="name"
                placeholder="Ana García Martínez"
                value={fullName}
                onChange={handleNameChange}
              />
              {fullName !== '' && !isValidName(fullName) && (
                <p className={styles.fieldError}>{NAME_HINT}</p>
              )}
            </div>

            <div className={styles.row}>
              <label className={styles.label} htmlFor="fru-email">
                Email
              </label>
              <input
                id="fru-email"
                className={styles.input}
                type="email"
                autoComplete="email"
                placeholder="ana.garcia@rodamientosdelsur.com"
                value={email}
                onChange={handleEmailChange}
              />
              {email !== '' && !isValidEmail(email) && (
                <p className={styles.fieldError}>{EMAIL_HINT}</p>
              )}
              {checking && (
                <p className={styles.status} role="status">
                  {EMAIL_CHECKING}
                </p>
              )}
              {emailAvailable && <p className={styles.emailOk}>{EMAIL_FREE}</p>}
              {emailTaken && (
                <p className={styles.fieldError} role="alert">
                  {EMAIL_TAKEN}
                </p>
              )}
            </div>

            <div className={styles.row}>
              <label className={styles.label} htmlFor="fru-password">
                Contraseña
              </label>
              <input
                id="fru-password"
                className={styles.input}
                type="password"
                autoComplete="new-password"
                placeholder="Mínimo 10 caracteres"
                value={password}
                onChange={handlePasswordChange}
              />
              <p className={styles.hint}>{PASSWORD_RULES}</p>
              {password !== '' && !isValidPassword(password) && (
                <p className={styles.fieldError}>{PASSWORD_HINT}</p>
              )}
            </div>

            <div className={styles.row}>
              <label className={styles.label} htmlFor="fru-repeat">
                Repetir contraseña
              </label>
              <input
                id="fru-repeat"
                className={styles.input}
                type="password"
                autoComplete="new-password"
                placeholder="Repite la contraseña"
                value={repeat}
                onChange={handleRepeatChange}
              />
              {repeat !== '' && repeat !== password && (
                <p className={styles.fieldError}>{PASSWORD_MISMATCH}</p>
              )}
            </div>

            <label className={styles.check} htmlFor="fru-terms">
              <input
                id="fru-terms"
                type="checkbox"
                checked={acceptedTerms}
                onChange={handleTermsChange}
              />
              <span>
                Acepto los{' '}
                <a href="#terminos" onClick={(event) => event.preventDefault()}>
                  Términos y Condiciones
                </a>{' '}
                de Bearingworld.io.
              </span>
            </label>

            <button type="submit" className={styles.button} disabled={!canSubmit}>
              Registrar usuario
            </button>

            {submitError !== null && (
              <p className={styles.alert} role="alert">
                {submitError}
              </p>
            )}
          </form>
        )}
      </div>
    </div>
  );
}
